import ezdxf
doc = ezdxf.readfile('20_drawings/C-101_Site_Utility_Plan_Rev4.dxf')
msp = doc.modelspace()

# Get all text with positions - look for stub-outs, borings, etc.
for entity in msp.query('TEXT MTEXT'):
    try:
        pos = entity.dxf.insert
        text = entity.dxf.text
        layer = entity.dxf.layer
        if 'STUB' in text or 'stub' in text or 'BORING' in text or 'B-' in text or 'BORING' in text:
            print(f'  Layer={layer} Pos=({pos.x:.1f},{pos.y:.1f}) Text={text[:200]}')
    except Exception as e:
        pass

# Get all circle entities (could be manholes, borings, etc.)
print()
print('=== CIRCLE entities ===')
for entity in msp.query('CIRCLE'):
    try:
        center = entity.dxf.center
        radius = entity.dxf.radius
        layer = entity.dxf.layer
        print(f'  Layer={layer} Center=({center.x:.1f},{center.y:.1f}) Radius={radius:.1f}')
    except Exception as e:
        pass

# Get polyline entities on other layers
print()
print('=== Polylines on other layers ===')
for entity in msp.query('LWPOLYLINE'):
    try:
        layer = entity.dxf.layer
        if layer not in ['BLDG']:
            points = list(entity.get_points())
            if len(points) >= 2:
                print(f'  Layer={layer} Points={len(points)} Start=({points[0][0]:.1f},{points[0][1]:.1f}) End=({points[-1][0]:.1f},{points[-1][1]:.1f})')
    except Exception as e:
        pass
"
